//! Ce qu'un slicer annonce sur une impression, ramené à un vocabulaire commun.
//!
//! Un fichier tranché (G-code, et 3MF de **projet**) n'annonce pas les mêmes
//! choses au même endroit selon le slicer :
//!
//! - **en tête** : `; generated by PrusaSlicer 2.7.4`, `;TIME:4321` (Cura),
//!   `;Filament used: 1.24m, 9.5g` ;
//! - **en pied**, après le toolpath, sous la forme d'un profil complet
//!   (`; key = value`) : c'est là que PrusaSlicer, SuperSlicer, OrcaSlicer,
//!   Bambu Studio et QIDISlicer écrivent `filament_type`, `layer_height`,
//!   `printer_model`… Un profil en compte des centaines de lignes, dont une
//!   poignée seulement parle d'autre chose que de réglages fins.
//!
//! Les **clés** changent d'un slicer (et d'une version) à l'autre : c'est ici
//! qu'elles sont ramenées à un vocabulaire fermé, que l'interface étiquette et
//! traduit et que les agents peuvent décrire. Rien n'est inventé : un champ que
//! le fichier ne porte pas reste `None`.

use schemars::JsonSchema;
use serde::Serialize;
use std::collections::BTreeMap;

/// Ce qu'on sait de l'impression, tous formats confondus.
///
/// Tous les champs sont facultatifs : un fichier jamais tranché (STL, OBJ) n'en
/// a aucun, et aucun slicer n'annonce tout.
#[derive(Clone, Debug, Default, PartialEq, Serialize, JsonSchema)]
pub struct PrintInfo {
    /// Durée d'impression estimée, en secondes.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub duration_seconds: Option<u64>,
    /// Matière annoncée (`PLA`, `PETG`…).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub material: Option<String>,
    /// Poids de filament, en grammes — **seulement si le slicer l'annonce**.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub filament_grams: Option<f64>,
    /// Hauteur de couche, en mm, telle qu'annoncée.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub layer_height: Option<String>,
    /// Hauteur de la première couche, en mm.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub first_layer_height: Option<String>,
    /// Diamètre de buse, en mm.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub nozzle: Option<String>,
    /// Imprimante visée.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub printer: Option<String>,
    /// Remplissage annoncé (ex. `100%`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub fill_density: Option<String>,
    /// Supports activés (`None` si le fichier ne le dit pas).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub support: Option<bool>,
    /// Encombrement de l'objet, en mm : `[X, Y, Z]`.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub size_mm: Option<[f64; 3]>,
    /// Slicer qui a produit le fichier (`QIDISlicer 1.2.5 on 2026-07-25…`).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub slicer: Option<String>,
    /// Taille du fichier sur le disque, en octets.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub bytes: Option<u64>,
}

/// Clés de profil qui **disent quelque chose** à qui ouvre le fichier.
///
/// Le profil d'un slicer en compte des centaines (`avoid_crossing_perimeters`,
/// `wipe_distance`…) : sans ce filtre, le plafond de lecture du **pied** serait
/// rempli par du bruit de réglages. Les noms sont ceux de [`normalize_key`], donc
/// `filament used [g]` s'écrit ici `filament_used_g`.
pub(crate) const KNOWN_KEYS: &[&str] = &[
    // Durée : PrusaSlicer / SuperSlicer / OrcaSlicer / Bambu Studio.
    "estimated_printing_time_normal_mode",
    "estimated_printing_time_silent_mode",
    "total_estimated_time",
    "print_time",
    "time",
    // Matière et quantité.
    "filament_type",
    "filament_used",
    "filament_used_g",
    "filament_used_m",
    "filament_used_mm",
    "filament_used_cm3",
    "total_filament_used_g",
    "total_filament_weight_g",
    "filament_weight",
    // Géométrie et machine.
    "layer_height",
    "layer_height_0",
    "first_layer_height",
    "nozzle_diameter",
    "printer_model",
    "fill_density",
    "support_material",
    // Provenance.
    "generated_by",
];

impl PrintInfo {
    /// `true` si le fichier n'annonce rien du tout.
    ///
    /// Sert à ne pas afficher une carte vide : un STL n'a pas d'informations
    /// d'impression, et une carte « Impression » sans ligne n'apprendrait rien.
    pub fn is_empty(&self) -> bool {
        *self == PrintInfo::default()
    }

    /// Remplit ce qui peut l'être à partir d'un profil de slicer (clés déjà
    /// normalisées par [`normalize_key`]).
    pub(crate) fn from_metadata(meta: &BTreeMap<String, String>) -> Self {
        Self {
            duration_seconds: value(
                meta,
                &[
                    "estimated_printing_time_normal_mode",
                    "estimated_printing_time_silent_mode",
                    "total_estimated_time",
                    "print_time",
                ],
            )
            .and_then(|v| parse_duration(&v))
            // Cura : `;TIME:4321` — des **secondes**, sans unité. Un autre
            // slicer peut écrire des unités sous la même clé (`1h 12m`) :
            // on essaie les secondes, puis les unités.
            .or_else(|| {
                value(meta, &["time"])
                    .and_then(|v| v.trim().parse::<u64>().ok().or_else(|| parse_duration(&v)))
            }),
            material: value(meta, &["filament_type"]),
            filament_grams: value(
                meta,
                &[
                    "filament_used_g",
                    "total_filament_used_g",
                    "total_filament_weight_g",
                    "filament_weight",
                    // Cura : `1.24m, 9.5g` — c'est le `g` qui compte.
                    "filament_used",
                ],
            )
            .and_then(|v| parse_grams(&v)),
            layer_height: value(meta, &["layer_height"]),
            first_layer_height: value(meta, &["first_layer_height", "layer_height_0"]),
            nozzle: value(meta, &["nozzle_diameter"]),
            printer: value(meta, &["printer_model"]),
            fill_density: value(meta, &["fill_density"]),
            support: value(meta, &["support_material"]).and_then(|v| parse_bool(&v)),
            // Ni la taille de l'objet ni le poids du fichier ne s'écrivent dans
            // le profil : ils se mesurent (voir `gcode::print_info`).
            size_mm: None,
            slicer: value(meta, &["generated_by"]),
            bytes: None,
        }
    }
}

/// Première valeur non vide parmi plusieurs clés.
fn value(meta: &BTreeMap<String, String>, keys: &[&str]) -> Option<String> {
    keys.iter()
        .find_map(|k| meta.get(*k))
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty())
}

/// Paire `clé → valeur` d'une ligne de commentaire, quelle que soit l'écriture
/// du slicer (`; clé = valeur`, `;clé:valeur`).
///
/// Volontairement strict : les lignes de données base64 du bloc de vignette
/// contiennent des `=` (padding) et ne doivent **pas** être prises pour des
/// métadonnées — d'où l'exigence d'un ` = ` entouré d'espaces, ou d'un `:`.
pub(crate) fn comment_pair(line: &str) -> Option<(String, String)> {
    let body = line.trim_start().strip_prefix(';')?.trim();
    if body.is_empty() {
        return None;
    }

    // `; generated by PrusaSlicer 2.7.4 on 2026-09-19` : la seule ligne utile qui
    // ne suive ni l'écriture `clé = valeur` ni l'écriture `clé:valeur`.
    let (raw_key, raw_value) = match body.split_once(" = ") {
        Some((key, value)) => (key, value),
        None => match body.split_once(':') {
            Some((key, value)) => (key, value),
            None => {
                let rest = body.strip_prefix("generated by ")?;
                ("generated_by", rest)
            }
        },
    };

    let key = normalize_key(raw_key);
    let value = raw_value.trim();
    if key.is_empty() || value.is_empty() {
        return None;
    }
    if key.chars().count() > META_KEY_MAX || value.chars().count() > META_VALUE_MAX {
        return None;
    }
    // Une valeur qui ressemble à du base64 (que des caractères d'alphabet
    // base64, très longue) n'est pas une métadonnée.
    if value.len() > 60
        && value
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '/' || c == '=')
    {
        return None;
    }

    Some((key, value.to_string()))
}

/// Longueurs acceptées pour une clé et une valeur de métadonnée.
const META_KEY_MAX: usize = 40;
const META_VALUE_MAX: usize = 200;

/// Clé de métadonnée : minuscules, séparateurs (` `, `(`, `-`…) réduits à un `_`.
pub(crate) fn normalize_key(raw: &str) -> String {
    let mut out = String::new();
    for c in raw.trim().to_ascii_lowercase().chars() {
        if c.is_ascii_alphanumeric() {
            out.push(c);
        } else if !out.ends_with('_') && !out.is_empty() {
            out.push('_');
        }
    }
    out.trim_end_matches('_').to_string()
}

/// Ajoute à `into` les paires `clé = valeur` lues dans `text`.
///
/// `only_known` restreint à [`KNOWN_KEYS`] : c'est le cas du **pied** de fichier,
/// où un profil complet noierait les quelques valeurs qui parlent. `max` borne le
/// nombre de paires ajoutées (0 = sans plafond).
pub(crate) fn collect_pairs(
    text: &str,
    only_known: bool,
    max: usize,
    into: &mut BTreeMap<String, String>,
) {
    for line in text.lines() {
        if max > 0 && into.len() >= max {
            return;
        }
        let Some((key, value)) = comment_pair(line) else {
            continue;
        };
        if only_known && !KNOWN_KEYS.contains(&key.as_str()) {
            continue;
        }
        into.entry(key).or_insert(value);
    }
}

/// Durée annoncée par un slicer, en secondes.
///
/// Écritures rencontrées : `1h 12m`, `1h 12m 3s`, `2 days 3h 15m`, `45 min`,
/// `1 hour 5 minutes` et `01:12:03`. Une valeur **sans unité** n'est pas acceptée
/// ici : les appelants savent, eux, dans quelle unité elle est écrite (`M73 R…`
/// compte des minutes, `;TIME:` des secondes).
pub(crate) fn parse_duration(raw: &str) -> Option<u64> {
    let lower = raw.trim().to_ascii_lowercase();

    // `01:12:03` ou `12:03` (heures:minutes[:secondes]).
    if lower.contains(':') {
        let parts: Vec<u64> = lower
            .split(':')
            .map(|p| p.trim().parse::<u64>().ok())
            .collect::<Option<Vec<_>>>()?;
        return match parts[..] {
            [h, m, s] => Some(h * 3600 + m * 60 + s),
            [m, s] => Some(m * 60 + s),
            _ => None,
        };
    }

    let mut total = 0u64;
    let mut trouve = false;
    for (nombre, unite) in number_unit_pairs(&lower) {
        let facteur = match unite.as_str() {
            "d" | "day" | "days" => 86_400,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3_600,
            "m" | "min" | "mins" | "minute" | "minutes" => 60,
            "s" | "sec" | "secs" | "second" | "seconds" => 1,
            _ => continue,
        };
        total += nombre.round().max(0.0) as u64 * facteur;
        trouve = true;
    }
    trouve.then_some(total)
}

/// Poids annoncé, en grammes.
///
/// Écritures rencontrées : `12.34` (PrusaSlicer, `filament used [g] = …`),
/// `9.5g` et `1.24m, 9.5g` (Cura). Une longueur en mètres ou un volume en cm³
/// n'est **pas** converti : sans densité, ce serait une invention.
pub(crate) fn parse_grams(raw: &str) -> Option<f64> {
    let lower = raw.trim().to_ascii_lowercase();
    let pairs = number_unit_pairs(&lower);

    // Un nombre suivi d'une unité de masse (`g`, `gr`, `gram`…).
    if let Some((nombre, _)) = pairs.iter().find(|(_, unite)| is_grams(unite)) {
        return Some(*nombre);
    }
    // Sinon un nombre nu : `12.34`.
    match pairs[..] {
        [(nombre, ref unite)] if unite.is_empty() => Some(nombre),
        _ => None,
    }
}

/// Unité de masse : `g`, `gr`, `gram`, `grams`. Pas `gcode`.
fn is_grams(unite: &str) -> bool {
    unite == "g" || unite == "gr" || unite.starts_with("gram")
}

/// `true`/`false` d'un réglage de slicer (`1`, `true`, `yes`…).
fn parse_bool(raw: &str) -> Option<bool> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "1" | "true" | "yes" | "on" => Some(true),
        "0" | "false" | "no" | "off" => Some(false),
        _ => None,
    }
}

/// Couples `nombre` + unité d'une chaîne (« 1h 12m 3s », « 45 min », « 9.5g »).
///
/// L'unité peut être **collée** au nombre (`12m`, `9.5g`) ou **détachée** par une
/// espace (`45 min`, `1 hour 5 minutes`) ; elle est vide quand le nombre est nu.
/// La casse est déjà abaissée par l'appelant.
fn number_unit_pairs(s: &str) -> Vec<(f64, String)> {
    let mut pairs = Vec::new();
    let mut mots = s.split_whitespace().peekable();

    while let Some(mot) = mots.next() {
        let Some((nombre, unite)) = split_number_unit(mot) else {
            continue;
        };
        let unite = if unite.is_empty() {
            // Unité détachée : le mot suivant, s'il en est une.
            match mots.peek().map(|suivant| clean_unit(suivant)) {
                Some(suivant) if is_unit_word(&suivant) => {
                    mots.next();
                    suivant
                }
                _ => String::new(),
            }
        } else {
            unite
        };
        pairs.push((nombre, unite));
    }
    pairs
}

/// Sépare un mot en (nombre, unité collée) : `1.24m,` → `(1.24, "m")`.
///
/// `None` si le mot ne commence pas par un nombre (une unité seule, un mot).
fn split_number_unit(mot: &str) -> Option<(f64, String)> {
    let mut nombre = String::new();
    let mut unite = String::new();
    for c in mot.chars() {
        if unite.is_empty() && (c.is_ascii_digit() || c == '.' || c == ',') {
            nombre.push(c);
        } else if c.is_ascii_alphabetic() {
            unite.push(c);
        }
    }
    if nombre.is_empty() {
        return None;
    }
    let valeur = nombre
        .trim_end_matches(',')
        .replace(',', ".")
        .parse::<f64>()
        .ok()?;
    Some((valeur, unite))
}

/// Unité débarrassée de la ponctuation qui la suit (`min,` → `min`).
fn clean_unit(mot: &str) -> String {
    mot.trim_matches(|c: char| !c.is_ascii_alphanumeric())
        .to_ascii_lowercase()
}

/// Unité **détachée** reconnue (`45 min`, `1 hour`, `12 g`).
///
/// Liste fermée : un mot quelconque qui suit un nombre n'est pas une unité
/// (`12.34 PLA` reste un nombre nu).
fn is_unit_word(mot: &str) -> bool {
    matches!(
        mot,
        "d" | "day"
            | "days"
            | "h"
            | "hr"
            | "hrs"
            | "hour"
            | "hours"
            | "m"
            | "min"
            | "mins"
            | "minute"
            | "minutes"
            | "s"
            | "sec"
            | "secs"
            | "second"
            | "seconds"
            | "g"
            | "gr"
            | "gram"
            | "grams"
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    fn meta(pairs: &[(&str, &str)]) -> BTreeMap<String, String> {
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect()
    }

    #[test]
    fn lit_les_ecritures_de_chaque_slicer() {
        // PrusaSlicer / QIDISlicer : `; key = value` dans le pied de fichier.
        assert_eq!(
            comment_pair("; layer_height = 0.2").unwrap().0,
            "layer_height"
        );
        assert_eq!(comment_pair("; layer_height = 0.2").unwrap().1, "0.2");
        // Cura : `;clé:valeur`, sans espace.
        assert_eq!(comment_pair(";TIME:4321").unwrap().0, "time");
        // PrusaSlicer : la seule ligne utile sans séparateur.
        assert_eq!(
            comment_pair("; generated by PrusaSlicer 2.7.4 on 2026-09-19")
                .unwrap()
                .0,
            "generated_by"
        );
        // Le `[g]` d'une clé Prusa devient un `_g` : c'est ce que lit `KNOWN_KEYS`.
        assert_eq!(
            comment_pair("; filament used [g] = 12.34").unwrap().0,
            "filament_used_g"
        );
        // Les lignes de vignette (base64, padding `=`) ne sont pas des données.
        assert!(comment_pair("; iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==").is_none());
        assert!(comment_pair(";").is_none());
    }

    #[test]
    fn le_pied_ne_garde_que_les_cles_qui_parlent() {
        let profil = "; avoid_crossing_perimeters = 1\n\
                      ; wipe_distance = 2\n\
                      ; filament_type = PLA\n\
                      ; layer_height = 0.2\n";
        let mut tout = BTreeMap::new();
        collect_pairs(profil, false, 0, &mut tout);
        assert_eq!(tout.len(), 4, "sans filtre, tout est gardé : {tout:?}");

        let mut utiles = BTreeMap::new();
        collect_pairs(profil, true, 0, &mut utiles);
        assert_eq!(utiles.len(), 2, "filtré : {utiles:?}");
        assert_eq!(utiles["filament_type"], "PLA");
        assert!(!utiles.contains_key("wipe_distance"));
    }

    #[test]
    fn durations_dans_toutes_les_ecritures() {
        assert_eq!(parse_duration("1h 12m"), Some(4320));
        assert_eq!(parse_duration("1h 12m 3s"), Some(4323));
        assert_eq!(parse_duration("45 min"), Some(2700));
        assert_eq!(
            parse_duration("2 days 3h 15m"),
            Some(2 * 86400 + 3 * 3600 + 15 * 60)
        );
        assert_eq!(parse_duration("1 hour 5 minutes"), Some(3900));
        assert_eq!(parse_duration("01:12:03"), Some(4323));
        assert_eq!(parse_duration("12:03"), Some(723));
        // Sans unité : à l'appelant de savoir (minutes de `M73`, secondes de Cura).
        assert_eq!(parse_duration("121"), None);
        assert_eq!(parse_duration(""), None);
    }

    #[test]
    fn poids_en_grammes_uniquement() {
        assert_eq!(parse_grams("12.34"), Some(12.34));
        assert_eq!(parse_grams("9.5g"), Some(9.5));
        assert_eq!(parse_grams("1.24m, 9.5g"), Some(9.5));
        assert_eq!(parse_grams("12,34 g"), Some(12.34));
        // Une longueur ou un volume n'est pas un poids : sans densité, convertir
        // serait inventer.
        assert_eq!(parse_grams("1.24m"), None);
        assert_eq!(parse_grams("2.5cm3"), None);
    }

    #[test]
    fn resume_d_un_profil_type_qidi() {
        let info = PrintInfo::from_metadata(&meta(&[
            (
                "generated_by",
                "QIDISlicer 1.2.5 on 2026-07-25 at 12:54:32 UTC",
            ),
            ("filament_type", "PLA"),
            ("layer_height", "0.2"),
            ("first_layer_height", "0.2"),
            ("nozzle_diameter", "0.4"),
            ("printer_model", "X-Plus 3"),
            ("fill_density", "100%"),
            ("support_material", "1"),
        ]));
        assert_eq!(info.material.as_deref(), Some("PLA"));
        assert_eq!(info.layer_height.as_deref(), Some("0.2"));
        assert_eq!(info.nozzle.as_deref(), Some("0.4"));
        assert_eq!(info.printer.as_deref(), Some("X-Plus 3"));
        assert_eq!(info.fill_density.as_deref(), Some("100%"));
        assert_eq!(info.support, Some(true));
        assert!(info.slicer.as_deref().unwrap().starts_with("QIDISlicer"));
        // Ni durée ni poids dans ce profil : on ne les invente pas.
        assert_eq!(info.duration_seconds, None);
        assert_eq!(info.filament_grams, None);
        assert!(!info.is_empty());
        assert!(PrintInfo::default().is_empty());
    }

    #[test]
    fn resume_d_un_profil_type_prusa() {
        let info = PrintInfo::from_metadata(&meta(&[
            ("estimated_printing_time_normal_mode", "2h 05m 30s"),
            ("filament_used_g", "12.34"),
            ("filament_type", "PETG"),
            ("support_material", "0"),
        ]));
        assert_eq!(info.duration_seconds, Some(2 * 3600 + 5 * 60 + 30));
        assert_eq!(info.filament_grams, Some(12.34));
        assert_eq!(info.support, Some(false));
    }
}
